function calendar(){var vehicles=state.data.vehicles.slice().sort(function(a,b){return String(a.name||"").localeCompare(String(b.name||""))}),rentals=state.data.rentals.filter(function(r){return r.status!=="cancelled"}),days=[];var base=new Date();base.setHours(0,0,0,0);for(var i=0;i<14;i++){var d=new Date(base);d.setDate(base.getDate()+i);days.push(d)}function iso(d){return d.toISOString().slice(0,10)}function booked(v,d){return rentals.find(function(r){if(String(r.vehicle_id)!==String(v.id))return false;var s=String(r.start_at||"").slice(0,10),e=String(r.end_at||r.start_at||"").slice(0,10),x=iso(d);return s&&e&&x>=s&&x<=e})}var head=days.map(function(d){return '<th>'+d.toLocaleDateString("en",{weekday:"short"})+'<br><strong>'+d.getDate()+'</strong></th>'}).join(""),body=vehicles.map(function(v){var cells=days.map(function(d){var r=booked(v,d);return '<td class="'+(r?'booked':'available')+'">'+(r?'<button class="calendarBooking" data-invoice="'+esc(r.id)+'">'+esc(r.invoice_no||"Booked")+'</button>':'<span>Available</span>')+'</td>'}).join("");return '<tr><td class="vehicleCell"><strong>'+esc(v.name||"Vehicle")+'</strong><small>'+esc(v.registration||v.category||"")+'</small></td>'+cells+'</tr>'}).join("");if(!vehicles.length)body='<tr><td colspan="15" class="empty">Add vehicles to see availability.</td></tr>';return header("Rental Calendar","14-day fleet availability at a glance.",'<button class="btn primary" data-action="booking">+ New booking</button>')+'<div class="calendarLegend"><span><i class="dot availableDot"></i> Available</span><span><i class="dot bookedDot"></i> Booked</span><button class="btn" data-tab="Bookings">Booking ledger</button></div><div class="calendarWrap"><table class="calendarTable"><thead><tr><th>Vehicle</th>'+head+'</tr></thead><tbody>'+body+'</tbody></table></div>'}
