function loadData(){var base=["vehicles","customers","services","rentals","expenses","maintenance"];if(can(state.user,"staff.manage"))base.push("staff");if(can(state.user,"reports.read")||can(state.user,"staff.manage"))base.push("audit");if(can(state.user,"fleet.read"))base.push("fleet-overview");return Promise.all(base.map(function(k){return api("/api/"+k).then(function(v){state.data[k==="fleet-overview"?"fleet":k]=v}).catch(function(){state.data[k==="fleet-overview"?"fleet":k]=[]})})).then(render)}
