function saveForm(type){var map={booking:"rentals",vehicle:"vehicles",customer:"customers",service:"services",expense:"expenses",maintenance:"maintenance",pickup:"rentals",return:"rentals"},b={},fields=document.querySelectorAll(".modalBox input,.modalBox select");fields.forEach(function(i){if(i.id.indexOf("f_")===0)b[i.id.slice(2)]=i.value});if(type==="fleet-inspection"){var ib={};fields.forEach(function(i){if(i.id.indexOf("f_")===0)ib[i.id.slice(2)]=i.value});try{ib.checklist=JSON.parse(ib.checklist||"{}")}catch(e){ib.checklist={}}return api("/api/fleet-inspection",{method:"POST",body:JSON.stringify(ib)}).then(function(){document.querySelector(".modal").remove();return loadData()}).catch(function(e){alert(e.message)})}if(type==="fleet-damage"){var db={};fields.forEach(function(i){if(i.id.indexOf("f_")===0)db[i.id.slice(2)]=i.value});return api("/api/vehicle-damage",{method:"POST",body:JSON.stringify(db)}).then(function(){document.querySelector(".modal").remove();return loadData()}).catch(function(e){alert(e.message)})}if(type==="financial"){return api("/api/rental-transaction",{method:"POST",body:JSON.stringify(b)}).then(function(){document.querySelector(".modal").remove();return loadData()}).catch(function(e){alert(e.message)})}if(type==="staff-edit"){var sid=b.id;delete b.id;return api("/api/staff/"+sid,{method:"PUT",body:JSON.stringify(b)}).then(function(){document.querySelector(".modal").remove();return loadData()}).catch(function(e){alert(e.message)})}if(type==="staff"){delete b.id;return api("/api/staff",{method:"POST",body:JSON.stringify(b)}).then(function(){document.querySelector(".modal").remove();return loadData()}).catch(function(e){alert(e.message)})}if(type==="customer-document"){return finishSave(type,b)}if(type==="customer-edit"){var id=b.id;delete b.id;return api("/api/customers/"+id,{method:"PUT",body:JSON.stringify(b)}).then(function(){document.querySelector(".modal").remove();return loadData()}).catch(function(e){alert(e.message)})}if(type==="booking"){var typed=String(value("f_customer_name")||"").trim(),match=state.data.customers.find(function(x){return String(x.name||"").trim().toLowerCase()===typed.toLowerCase()});if(!typed)return alert("Enter a customer name.");if(match){b.customer_id=match.id}else{var nb={name:typed,phone:b.new_customer_phone||"",email:b.new_customer_email||"",nationality:b.new_customer_nationality||"",id_reference:b.new_customer_id_reference||""};return api("/api/customers",{method:"POST",body:JSON.stringify(nb)}).then(function(r){b.customer_id=r.id;return finishSave(type,b)}).catch(function(e){alert(e.message)})}}finishSave(type,b)}
